// ══════════════════════════════════════════════════════════════
// GOOGLE PLAY BRAND (12 Nov 2026) — in the Play app only, the app is called "Qi FAST".
// Google Play does not allow a government programme's acronym in an app's name or icon, so the
// Play app shows "Qi FAST" and the Qi FAST logo; the website stays NQAS | FAST.
// Mentions of the NQAS standards inside the content are descriptive and stay.
// ══════════════════════════════════════════════════════════════
var NF_PLAY_BRAND = (function () {
  var play = false;
  try {
    if (/[?&]src=play\b/.test(location.search || '') || /^android-app:\/\/com\.thehealsol\.(?:nqasfast|qifast)(\/|$)/.test(document.referrer || '')) sessionStorage.setItem('nf_play', '1');
    play = sessionStorage.getItem('nf_play') === '1';
  } catch (e) {}
  if (!play) return null;
  var B = { name: 'Qi FAST', mark: 'data:image/jpeg;base64,', icon: 'data:image/png;base64,' };
  try {
    if (typeof SC_BRAND === 'object') { SC_BRAND.name = B.name; SC_BRAND.nameHTML = 'Qi FAST'; SC_BRAND.logoNqas = B.mark; SC_BRAND.logoMark = B.icon; }
    document.documentElement.classList.add('nf-play-brand');
  } catch (e) {}
  var RX = /NQAS ?\| ?FAST|NQAS FAST/g, SKIP = { SCRIPT: 1, STYLE: 1, TEXTAREA: 1, NOSCRIPT: 1 };
  function fixText(n) { if (n.nodeValue && n.nodeValue.indexOf('NQAS') >= 0 && n.parentNode && !SKIP[n.parentNode.nodeName]) { var v = n.nodeValue.replace(RX, B.name); if (v !== n.nodeValue) n.nodeValue = v; } }
  // "NQAS<i>|</i>FAST" written as markup: three nodes
  function fixSplit(i) {
    if (i.textContent !== '|') return; var a = i.previousSibling, z = i.nextSibling;
    if (a && z && a.nodeType === 3 && z.nodeType === 3 && /NQAS\s*$/.test(a.nodeValue) && /^\s*FAST/.test(z.nodeValue)) { a.nodeValue = a.nodeValue.replace(/NQAS\s*$/, 'Qi '); z.nodeValue = z.nodeValue.replace(/^\s*/, ''); i.remove(); }
  }
  function fixImg(img) { var alt = img.getAttribute('alt') || ''; if (/^NQAS(\.QI)?$/.test(alt)) { img.setAttribute('alt', 'Qi FAST'); if (img.src.indexOf('data:') === 0 && img.src !== B.mark && img.src !== B.icon) img.src = img.classList.contains('nf-mark') ? B.icon : B.mark; } }
  function walk(root) {
    if (!root) return;
    if (root.nodeType === 3) return fixText(root);
    if (root.nodeType !== 1 || SKIP[root.nodeName]) return;
    if (root.nodeName === 'I') fixSplit(root); if (root.nodeName === 'IMG') fixImg(root);
    var w = document.createTreeWalker(root, NodeFilter.SHOW_TEXT), n; while ((n = w.nextNode())) fixText(n);
    root.querySelectorAll && root.querySelectorAll('i').forEach(fixSplit);
    root.querySelectorAll && root.querySelectorAll('img[alt^="NQAS"]').forEach(fixImg);
  }
  function title() { if (/NQAS/.test(document.title)) document.title = document.title.replace(RX, B.name); }
  function start() {
    walk(document.body); title();
    try {
      new MutationObserver(function (ms) {
        for (var k = 0; k < ms.length; k++) { var m = ms[k];
          if (m.type === 'characterData') fixText(m.target);
          else for (var j = 0; j < m.addedNodes.length; j++) walk(m.addedNodes[j]);
        }
        title();
      }).observe(document.documentElement, { subtree: true, childList: true, characterData: true });
    } catch (e) {}
  }
  if (document.body) start(); else document.addEventListener('DOMContentLoaded', start);
  return B;
})();
